WITH ranked_all AS(SELECT pb.id_user,pb.id_level,pb.id_record,points.points AS level_points,RANK() OVER(PARTITION BY pb.id_level ORDER BY record.time)::integer AS level_position FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=pb.id_record JOIN public.level_points points ON points.id_level=pb.id_level WHERE pb.id_level=ANY($1) AND points.points>0),ranked AS(SELECT * FROM ranked_all WHERE id_user=ANY($2)),desired AS(SELECT ranked.*,CASE WHEN ln(ranked.level_points::double precision)+(ranked.level_position-1)*ln(0.985)<ln(1.401298464324817e-45) THEN 0 ELSE ranked.level_points::double precision*power(0.985,ranked.level_position-1) END AS level_decayed_points FROM ranked) INSERT INTO public.user_point_contribution(id_user,id_level,id_record,contribution_rank,level_position,level_points,level_decayed_points,player_decayed_points,date_calculated) SELECT desired.id_user,desired.id_level,desired.id_record,coalesce(existing.contribution_rank,2147483647),desired.level_position,desired.level_points,desired.level_decayed_points,coalesce(existing.player_decayed_points,0),clock_timestamp() FROM desired LEFT JOIN public.user_point_contribution existing ON existing.id_user=desired.id_user AND existing.id_level=desired.id_level ON CONFLICT(id_user,id_level) DO UPDATE SET id_record=excluded.id_record,level_position=excluded.level_position,level_points=excluded.level_points,level_decayed_points=excluded.level_decayed_points,date_calculated=excluded.date_calculated WHERE ROW(user_point_contribution.id_record,user_point_contribution.level_position,user_point_contribution.level_points,user_point_contribution.level_decayed_points) IS DISTINCT FROM ROW(excluded.id_record,excluded.level_position,excluded.level_points,excluded.level_decayed_points) RETURNING id_user AS id
